-- AGRI SUPPLY DATABASE
-- SQLite schema for a rice and vegetables e-commerce system.
-- Run this file against database.db.
-- Passwords must be stored as secure hashes generated by the Flask application,
-- never as plain text.

PRAGMA foreign_keys = ON;

-- 1. USERS: login accounts for administrators and customers.
CREATE TABLE IF NOT EXISTS users (
    user_id INTEGER PRIMARY KEY AUTOINCREMENT,
    full_name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE COLLATE NOCASE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'customer'
        CHECK (role IN ('admin', 'customer')),
    is_active INTEGER NOT NULL DEFAULT 1
        CHECK (is_active IN (0, 1)),
    email_verified INTEGER NOT NULL DEFAULT 1
        CHECK (email_verified IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 1a. ACCOUNT TOKENS: hashed, single-use email and password-reset links.
CREATE TABLE IF NOT EXISTS account_tokens (
    token_hash TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    purpose TEXT NOT NULL
        CHECK (purpose IN ('verify_email', 'reset_password')),
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_account_tokens_user_purpose
    ON account_tokens(user_id, purpose);

-- 2. SUPPLIERS: farmers and agricultural suppliers.
CREATE TABLE IF NOT EXISTS suppliers (
    supplier_id INTEGER PRIMARY KEY AUTOINCREMENT,
    supplier_name TEXT NOT NULL,
    contact_person TEXT,
    phone TEXT,
    email TEXT,
    address TEXT,
    is_active INTEGER NOT NULL DEFAULT 1
        CHECK (is_active IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 3. CUSTOMERS: customer delivery/contact profile.
-- A customer can be linked to a user login account.
CREATE TABLE IF NOT EXISTS customers (
    customer_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER UNIQUE,
    phone TEXT,
    delivery_address TEXT,
    city TEXT,
    province TEXT,
    postal_code TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(user_id)
        ON UPDATE CASCADE ON DELETE SET NULL
);

-- 4. CATEGORIES: Rice and Vegetables.
CREATE TABLE IF NOT EXISTS categories (
    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
    category_name TEXT NOT NULL UNIQUE COLLATE NOCASE,
    description TEXT
);

-- 5. PRODUCTS: products offered for sale.
CREATE TABLE IF NOT EXISTS products (
    product_id INTEGER PRIMARY KEY AUTOINCREMENT,
    supplier_id INTEGER,
    category_id INTEGER NOT NULL,
    product_name TEXT NOT NULL,
    description TEXT,
    unit TEXT NOT NULL DEFAULT 'kg',
    price REAL NOT NULL CHECK (price >= 0),
    image_filename TEXT,
    is_available INTEGER NOT NULL DEFAULT 1
        CHECK (is_available IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        ON UPDATE CASCADE ON DELETE SET NULL,
    FOREIGN KEY (category_id) REFERENCES categories(category_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

-- 6. INVENTORY: current stock for each product.
CREATE TABLE IF NOT EXISTS inventory (
    inventory_id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id INTEGER NOT NULL UNIQUE,
    quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    reorder_level INTEGER NOT NULL DEFAULT 5 CHECK (reorder_level >= 0),
    last_updated TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
        ON UPDATE CASCADE ON DELETE CASCADE
);

-- 7. TRANSACTIONS: order line items.
-- Each product in a customer's order is stored as one row.
-- Rows belonging to the same checkout share the same order_reference.
CREATE TABLE IF NOT EXISTS transactions (
    transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_reference TEXT NOT NULL,
    customer_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price REAL NOT NULL CHECK (unit_price >= 0),
    total_amount REAL NOT NULL CHECK (total_amount >= 0),
    payment_method TEXT,
    payment_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (payment_status IN ('pending', 'paid', 'failed', 'refunded')),
    payment_received_at TEXT,
    order_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (order_status IN ('pending', 'confirmed', 'processing',
                                'shipped', 'delivered', 'cancelled')),
    delivery_address TEXT NOT NULL DEFAULT '',
    order_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

-- Helpful indexes for common searches and reports.
CREATE INDEX IF NOT EXISTS idx_products_category
    ON products(category_id);
CREATE INDEX IF NOT EXISTS idx_products_supplier
    ON products(supplier_id);
CREATE INDEX IF NOT EXISTS idx_transactions_order_reference
    ON transactions(order_reference);
CREATE INDEX IF NOT EXISTS idx_transactions_customer
    ON transactions(customer_id);
CREATE INDEX IF NOT EXISTS idx_transactions_order_date
    ON transactions(order_date);
CREATE INDEX IF NOT EXISTS idx_transactions_order_status
    ON transactions(order_status);

-- 8. ORDER STATUS HISTORY: timestamped fulfillment milestones for tracking.
CREATE TABLE IF NOT EXISTS order_status_history (
    history_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_reference TEXT NOT NULL,
    order_status TEXT NOT NULL
        CHECK (order_status IN ('pending', 'confirmed', 'processing',
                                'shipped', 'delivered', 'cancelled')),
    changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_order_status_history_reference
    ON order_status_history(order_reference, changed_at);

