        ('Brown Rice', 'Rice', 'Sample brown rice. Update the description and price as needed.', 65.00, 'brown.jpg'),
        ('Red Rice', 'Rice', 'Sample red rice. Update the description and price as needed.', 70.00, 'red.jpg'),
        ('Black Rice', 'Rice', 'Sample black rice. Update the description and price as needed.', 75.00, 'black rice.jpg'),
        ('Glutinous Rice', 'Rice', 'Sticky rice, called malagkit in the Philippines. Sample price; update as needed.', 65.00, 'Glutinous (sticky) rice, called malagkit in the Philippines.jpg'),
        ('Basmati Rice', 'Rice', 'Sample basmati rice. Update the description and price as needed.', 90.00, 'Basmati rice.jpg'),
        ('Eggplant', 'Vegetables', 'Sample fresh eggplant. Update the description and price as needed.', 60.00, 'Eggplant.jpg'),
        ('Bitter Melon', 'Vegetables', 'Ampalaya. Sample price; update as needed.', 70.00, 'Bitter melon (ampalaya).jpg'),
        ('Water Spinach', 'Vegetables', 'Kangkong. Sample price; update as needed.', 40.00, 'Water spinach (kangkong).jpg'),
        ('Okra', 'Vegetables', 'Sample fresh okra. Update the description and price as needed.', 60.00, 'Okra.jpg'),
        ('String Beans', 'Vegetables', 'Sitaw. Sample price; update as needed.', 70.00, 'String beans (sitaw)jpg.jpg'),
        ('Pechay', 'Vegetables', 'Bok choy. Sample price; update as needed.', 50.00, 'Pechay (bok choy).jpg'),
        ('Squash', 'Vegetables', 'Kalabasa. Sample price; update as needed.', 45.00, 'Squash (kalabasa.jpg'),
        ('Tomato', 'Vegetables', 'Sample fresh tomatoes. Update the description and price as needed.', 80.00, 'Tomato.jpg'),
        ('Carrot', 'Vegetables', 'Sample fresh carrots. Update the description and price as needed.', 70.00, 'Carrot.jpg'),
        ('Cabbage', 'Vegetables', 'Sample fresh cabbage. Update the description and price as needed.', 60.00, 'Cabbages.jpg')
)
INSERT INTO products
    (supplier_id, category_id, product_name, description, unit, price, image_filename)
SELECT s.supplier_id, c.category_id, starter.product_name,
       starter.description, 'kg', starter.price, starter.image_filename
FROM starter_products AS starter
JOIN categories AS c ON c.category_name = starter.category_name
JOIN suppliers AS s
  ON s.supplier_name = CASE starter.category_name
      WHEN 'Rice' THEN 'Sample Rice Farm'
      ELSE 'Sample Vegetable Farm'
  END
WHERE NOT EXISTS (
    SELECT 1 FROM products AS existing
    WHERE lower(existing.product_name) = lower(starter.product_name)
);

-- Create initial inventory rows for all starter products.
INSERT OR IGNORE INTO inventory (product_id, quantity, reorder_level)
SELECT product_id, 50, 5 FROM products;
